{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/icon-wall.json
    A dense grid of small tiles: an icon and a short label. Axes: columns (3, 4, 6), item (tile: icon above the label, chip: icon beside it), tone, density.
    Props (p): id, title, features, empty, cols, item, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_features = ($p['features'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_cols = ($p['cols'] ?? '4')}
{var $v_item = ($p['item'] ?? 'tile')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{var $v_askedCols = (og_t(og_and([og_eq($v_item, 'chip'), og_eq($v_cols, '6')])) ? '2-6' : (og_t(og_eq($v_cols, '2')) ? '2' : (og_t(og_eq($v_cols, '3')) ? '2-3' : (og_t(og_eq($v_cols, '4')) ? '2-4' : '3-6'))))}
{var $v_wallCols = og_fit_cols($v_askedCols, og_len($v_features))}
{capture $c_4}
  {if og_t(og_eq(og_len($v_features), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'layout-grid', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_3}
      {foreach og_l($v_features) as $v_f}
        {capture $c_2}
          {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_f, ['icon'])), 'size' => og_i((og_t(og_eq($v_item, 'tile')) ? 24 : 16))])|noescape}
          {capture $c_1}
            {=og_text(og_get($v_f, ['title']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
        {/capture}
        {=og_include('compose/Box.latte', ['class' => og_s(og_cnv(['flex items-center gap-2', 'rounded bg-card inset-ring inset-ring-border', (og_t(og_eq($v_item, 'tile')) ? og_cnv(['flex-col justify-center text-center', (og_t(og_eq($v_density, 'compact')) ? 'p-4' : 'p-6')]) : 'px-4 py-2')])), 'attrs' => og_attrs(['data-slot', 'item']), 'children' => (string) $c_2])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => og_s($v_wallCols), 'class' => 'gap-4', 'attrs' => og_attrs(['data-slot', 'items']), 'children' => (string) $c_3])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_4)])|noescape}
